update public.program_catalog_ca_staging set official_program_url=case id when 5531 then 'https://admissions.usask.ca/agronomy.php' when 5553 then 'https://admissions.usask.ca/agribusiness.php' else official_program_url end,source_status='official_program_page_verified_international_winter_2027_open',source_as_of=date '2026-08-08' where id in (5531,5553) and institution_name='University of Saskatchewan';
update public.program_pgwp_ca_staging p set international_students_eligible=true,international_program_admission_status='official_program_page_international_winter_2027_open_deadline_2026_09_01',source_url=case p.program_catalog_id when 5531 then 'https://admissions.usask.ca/agronomy.php' when 5553 then 'https://admissions.usask.ca/agribusiness.php' else p.source_url end,source_as_of=date '2026-08-08',verified_at=now(),rule_notes=concat_ws(' ',nullif(p.rule_notes,''),'USask current admissions page checked 2026-08-08: January 2027 international applications are open with a September 1, 2026 application deadline and October 1 document deadline.') where p.program_catalog_id in (5531,5553);;
